            // Bordered formats
            if let Some(borders) = borders {
                // Top border
                print!("{}{}", indent_str, borders.top_left);
                for (j, width) in col_widths.iter().enumerate() {
                    print!("{}", borders.horizontal.to_string().repeat(*width));
                    if j < col_widths.len() - 1 {
                        print!("{}", borders.top_mid);
                    }
                }
                println!("{}", borders.top_right);

                // Rows
                for (i, record) in records.iter().enumerate() {
                    print!("{}{}", indent_str, borders.left);
                    for (j, cell) in record.iter().enumerate() {
                        let width = col_widths.get(j).copied().unwrap_or(0);
                        let inner_width = width.saturating_sub(2 * args.padding);
                        let align = if i == 0 && !args.no_headers { &args.header_align } else { &args.body_align };
                        let aligned = align_text(cell, inner_width, align);
                        let padded = format!("{}{}{}", " ".repeat(args.padding), aligned, " ".repeat(args.padding));
                        print!("{}", padded);
                        if j < record.len() - 1 {
                            print!("{}", borders.vertical);
                        }
                    }
                    println!("{}", borders.right);

                    // Middle border after header or in grid mode
                    if (i == 0 && !args.no_headers) || (matches!(args.style, TableStyle::Grid) && i < records.len() - 1) {
                        print!("{}{}", indent_str, borders.mid_left);
                        for (j, width) in col_widths.iter().enumerate() {
                            print!("{}", borders.mid_mid.to_string().repeat(*width));
                            if j < col_widths.len() - 1 {
                                print!("{}", borders.mid_cross);
                            }
                        }
                        println!("{}", borders.mid_right);
                    }
